1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Step = {
23	  op: string;
24	  items: Item[];
25	};
26	
27	export type Item = { type: string } & Record<string, unknown>;
28	
29	export type Result = { premium: number };
30	
31	export type ScenarioOutcome = { results: Result[] };
32	
33	/** Sum of the base premiums of every item on a policy. */
34	const calculateBasePremium = (items: Item[]): number =>
35	  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
36	
37	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
38	const roundPremium = (amount: number): number => Math.ceil(amount);
39	
40	/** Price a policy covering the given items. */
41	const quotePremium = (items: Item[]): number => {
42	  const policyBasePremium = calculateBasePremium(items);
43	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
44	  return roundPremium(
45	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
46	  );
47	};
48	
49	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
50	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
51	});
